export async function hedgedDistill(url, cfg) {
  const t0 = Date.now()
  const meta = { hedgeStartedAt: null }
  let primarySettled = false
  const startHedge = () => { meta.hedgeStartedAt = Date.now() - t0 }
  const primary = fetch(url)
  const timer = setTimeout(() => { if (!primarySettled) startHedge() }, cfg.hedgeAfterMs)
  primary.then(() => { primarySettled = true })
  await primary.catch(() => {})
  clearTimeout(timer)
  return meta
}
import http from 'node:http'

/** 起一个本地 HTTP 服务：主请求延迟 primaryDelayMs 后回 status；返回 { url, close } */
export function fakeServer({ primaryDelayMs, status = 200 }) {
  const server = http.createServer((req, res) => {
    setTimeout(() => { res.writeHead(status, { 'content-type': 'application/json' }); res.end(JSON.stringify({ ok: true })) }, primaryDelayMs)
  })
  server.listen(0)
  const port = server.address().port
  return { url: `http://127.0.0.1:${port}/distill`, close: () => server.close() }
}
